const LanguageContext = createContext<{lang: Lang; setLang: (lang: Lang) => void; t: typeof copy.en}>({ lang: 'en', setLang: () => undefined, t: copy.en });
const useLanguage = () => useContext(LanguageContext);

function AppProvider({ children }: { children: ReactNode }) {
  const [lang, setLang] = useState<Lang>(() => (localStorage.getItem('mn-lang') as Lang) || 'en');
  useEffect(() => { localStorage.setItem('mn-lang', lang); document.documentElement.dir = lang === 'ar' || lang === 'darija' ? 'rtl' : 'ltr'; document.documentElement.lang = lang; }, [lang]);
  const value = useMemo(() => ({ lang, setLang, t: copy[lang] }), [lang]);
  return <LanguageContext.Provider value={value}>{children}</LanguageContext.Provider>;
}

